using System;using System.Collections;using System.Collections.Concurrent;using System.Collections.Generic;using System.Globalization;using System.IO;using System.Linq;using System.Net.Sockets;using System.Reflection;using System.Text;using System.Threading;using MelonLoader;using Newtonsoft.Json.Linq;
[assembly:MelonInfo(typeof(ShenPulseFusion.Bridge),"ShenPulse Fusion Bridge","1.0.0","ShenPulse")]
namespace ShenPulseFusion {
 public sealed class Bridge:MelonMod {
  sealed class Work {public JObject Request;public int Generation;public DateTime Expires;}
  readonly ConcurrentQueue<Work> queue=new ConcurrentQueue<Work>();readonly object writeLock=new object();CancellationTokenSource stop;TcpClient client;NetworkStream stream;int generation;IDictionary routes;Type appType;
  public override void OnInitializeMelon(){stop=new CancellationTokenSource();new Thread(NetworkLoop){IsBackground=true,Name="ShenPulse Fusion local bridge"}.Start();}
  void NetworkLoop(){while(!stop.IsCancellationRequested){try{using(var tcp=new TcpClient()){client=tcp;tcp.Connect("127.0.0.1",58827);stream=tcp.GetStream();int current=Interlocked.Increment(ref generation);var buffer=new List<byte>();byte[] chunk=new byte[4096];while(!stop.IsCancellationRequested){int read=stream.Read(chunk,0,chunk.Length);if(read==0)break;for(int i=0;i<read;i++){if(chunk[i]!=0){buffer.Add(chunk[i]);if(buffer.Count>65536)throw new InvalidDataException();continue;}if(buffer.Count==0)continue;var request=JObject.Parse(Encoding.UTF8.GetString(buffer.ToArray()));buffer.Clear();if((int?)request["type"]==255)continue;if(queue.Count>=128){Reply(request,3,"File d'interactions pleine.",current);continue;}queue.Enqueue(new Work{Request=request,Generation=current,Expires=DateTime.UtcNow.AddSeconds(8)});}}}}catch(Exception){ }finally{stream=null;client=null;Interlocked.Increment(ref generation);}stop.Token.WaitHandle.WaitOne(1000);}}
  void Reply(JObject request,int status,string message,int epoch){if(epoch!=Volatile.Read(ref generation))return;try{byte[] bytes=Encoding.UTF8.GetBytes(new JObject{["id"]=request["id"],["status"]=status,["message"]=message}.ToString(Newtonsoft.Json.Formatting.None)+"\0");lock(writeLock){stream?.Write(bytes,0,bytes.Length);}}catch{}}
  bool Ready(){try{if(routes==null){var type=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("ShenPulseFusion.Engine.Effects",false)).FirstOrDefault(t=>t!=null);if(type==null)return false;routes=(IDictionary)type.GetMethod("RegisterRoutes",BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(Activator.CreateInstance(type,true),null);}if(appType==null)appType=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("Il2Cpp.GameAPP",false)).FirstOrDefault(t=>t!=null);if(appType==null)return false;var flags=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static;object value=appType.GetProperty("theGameStatus",flags)?.GetValue(null)??appType.GetField("theGameStatus",flags)?.GetValue(null);return value!=null&&Convert.ToInt32(value,CultureInfo.InvariantCulture)==0;}catch{return false;}}
  public override void OnUpdate(){for(int n=0;n<16&&queue.TryDequeue(out var work);n++){if(work.Generation!=Volatile.Read(ref generation))continue;var request=work.Request;if(work.Expires<DateTime.UtcNow||!Ready()){Reply(request,3,"Chargez une partie jouable.",work.Generation);continue;}try{string code=(string)request["code"]??"";int queryAt=code.IndexOf('?');string route="/"+(queryAt<0?code:code.Substring(0,queryAt)).TrimStart('/').ToLowerInvariant();if(!routes.Contains(route)){Reply(request,2,"Interaction inconnue.",work.Generation);continue;}var parameters=request["parameters"] as JObject;var value=parameters?["effectValue"]?.ToString()??"0";if(queryAt>=0)foreach(string pair in code.Substring(queryAt+1).Split('&')){var parts=pair.Split(new[]{'='},2);if(parts.Length==2&&parts[0]=="effect")value=Uri.UnescapeDataString(parts[1]);}var body=new JObject{["effect"]=value,["username"]=(string)request["viewer"]??"Viewer",["avatarUrl"]=""};int quantity=Math.Max(1,Math.Min(20,(int?)request["quantity"]??1));for(int q=0;q<quantity;q++)((Delegate)routes[route]).DynamicInvoke(body);Reply(request,0,"Interaction executee.",work.Generation);}catch(Exception error){LoggerInstance.Warning("Interaction refusee : "+(error.InnerException??error).GetType().Name);Reply(request,1,"Le jeu a refuse cette interaction.",work.Generation);}}}
  public override void OnDeinitializeMelon(){stop?.Cancel();try{client?.Close();}catch{}while(queue.TryDequeue(out _)){} }
 }
}
